export const DAY=86400000;
const mod=(a,b)=>(a%b+b)%b;
export function regularAt(now,config){const day=Math.floor(now/DAY),anchor=Date.parse(config.anchor.date)/DAY,offset=mod(day-anchor,config.events.length*config.duration_days),index=Math.floor(offset/config.duration_days),start=(day-offset%config.duration_days)*DAY;return{name:config.events[index],day:offset%config.duration_days+1,start,end:start+config.duration_days*DAY};}
export function pvpAt(now,config){const block=config.registration_days+config.duration_days,day=Math.floor(now/DAY),anchor=Date.parse(config.anchor.date)/DAY,offset=mod(day-anchor,config.events.length*block),index=mod(config.events.indexOf(config.anchor.event)+Math.floor(offset/block),config.events.length),position=offset%block,registrationDate=(day-position)*DAY,start=registrationDate+config.registration_days*DAY;return{name:config.events[index],registration:position<config.registration_days,day:position-config.registration_days+1,registrationDate,start,end:start+config.duration_days*DAY};}
export function hordeAt(now,config){const position=mod(now/1000,config.cycle_seconds),live=position>=config.rest_seconds;return{live,end:now+((live?config.cycle_seconds:config.rest_seconds)-position)*1000};}
export function dayEvents(ms,data){const r=regularAt(ms,data.events.regular),p=pvpAt(ms,data.events.pvp);return[{name:r.name,label:({'Fishing Contest':'Fish','Cozy Farm':'Farm','Treasure Hunt':'Treasure','Raft Race':'Raft','Zobo Shooter':'Zobo'})[r.name]+' D'+r.day}, {name:p.name.startsWith('Gold Rush')?'Gold Rush':p.name,label:(p.name.startsWith('Gold Rush')?'GR '+p.name.split('#')[1]:'Dune')+(p.registration?' Reg':' D'+p.day),fullName:p.name,registration:p.registration,day:p.day}];}
